use vstd::prelude::*;

verus! {
    /// A loop‐invariant predicate saying that in the prefix a[0..i],
    /// min_idx< i, every a[min_idx] is ≤ every a[j] (j<i),
    /// and moreover for k<min_idx we have a[k]>a[min_idx].
    spec fn inv(a: Seq<i8>, i: nat, min_idx: nat) -> bool
        decreases 0
    {
        1 <= i && i <= a.len() &&
        min_idx < i &&
        forall |j: nat| j < i ==> a[min_idx] <= a[j] &&
        forall |k: nat| k < min_idx ==> a[k] > a[min_idx]
    }

    fn argmin(a: Vec<i8>) -> (result: usize)
        requires
            a.len() > 0,
        ensures
            // result is in‐bounds
            result < a.len(),
            // a[result] is ≤ every element
            forall |i: usize| i < a.len() ==> a[result] <= a[i],
            // and every earlier position is strictly greater
            forall |j: usize| j < result ==> a[j] > a[result],
    {
        let n: usize = a.len();
        let mut min_idx: usize = 0;
        let mut i: usize = 1;
        // Invariant: in a[0..i], min_idx is the first minimum
        while i < n
            invariant
                inv(a@, i as nat, min_idx as nat),
            decreases n - i,
        {
            let old_i = i;
            let old_min = min_idx;
            if a[i] < a[min_idx] {
                // we found a new strictly smaller value
                min_idx = i;
            }
            // advance to the next position
            i = old_i + 1;
            proof {
                // Now we must re‐establish inv(a@, i, min_idx).
                // By construction 1 <= i <= n, and i = old_i+1.
                assert(1 <= i && i <= n);
                if a@[old_i] < a@[old_min] {
                    // Case 1: we updated min_idx = old_i
                    assert(min_idx == old_i);
                    // min_idx < i
                    assert(min_idx < i);
                    // Show ∀ j<i. a[min_idx] <= a[j]:
                    assert(forall|j: usize| j < i ==> a[min_idx] <= a[j]) by {
                        // split on whether j<old_i or j==old_i
                        assert(forall|j: usize| j < old_i ==> {
                            // from old inv: a[old_min] <= a[j]
                            // and we know a[old_i] < a[old_min]
                            a@[min_idx] <= a@[j]
                        });
                        // the case j == old_i is trivial: a[old_i] <= a[old_i].
                    };
                    // Show ∀ k<min_idx. a[k] > a[min_idx]:
                    assert(forall|k: usize| k < min_idx ==> a[k] > a[min_idx]) by {
                        // here min_idx=old_i, so k<old_i.
                        // If k<old_min, old inv gives a[k]>a[old_min],
                        // and a[old_i]<a[old_min], so a[k]>a[old_i].
                        // If old_min<=k<old_i, old inv gives a[old_min] <= a[k],
                        // still a[old_min]>a[old_i], so a[k]>a[old_i].
                    };
                } else {
                    // Case 2: we kept the old minimum
                    assert(min_idx == old_min);
                    // old_min < old_i < old_i+1 = i
                    assert(min_idx < i);
                    // ∀ j<i. a[min_idx] <= a[j]
                    assert(forall|j: usize| j < i ==> a[min_idx] <= a[j]) by {
                        // if j<old_i, old inv covers it;
                        // if j==old_i, old inv says a[old_min] <= a[old_i].
                    };
                    // ∀ k<min_idx. a[k] > a[min_idx] holds as before
                    assert(forall|k: usize| k < min_idx ==> a[k] > a[min_idx]);
                }
            }
        }
        // At loop exit i==n, so inv(a@, n, min_idx) unfolds exactly to:
        //   min_idx<n, ∀j<n. a[min_idx]<=a[j], ∀k<min_idx. a[k]>a[min_idx]
        min_idx
    }
}

fn main() {
    // simple smoke‐tests
    let v1: Vec<i8> = vec![5];
    assert(argmin(v1) == 0);

    let v2: Vec<i8> = vec![3, 1, 4, 1, 5];
    assert(argmin(v2) == 1);

    let v3: Vec<i8> = vec![-2, -3, -3, -1];
    assert(argmin(v3) == 1);
}